const section=()=>{const s=sections.find(s=>s.id===state.section),indices=factSections[state.bookSection];if(!indices||!['foundations','chemistry'].includes(s.id))return s;const book=chapters.find(c=>c.id===s.chapter)?.sections.find(x=>x[0]===state.bookSection);return {...s,title:book?.[1]||s.title,summary:`A focused essentials review for textbook section ${state.bookSection}. Read the original section for complete coverage.`,facts:indices.map(i=>({...s.facts[i],originalId:`${s.id}/concept/${i}`}))};}, currentView=()=>section().views[state.view];
const normalize=s=>String(s).toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\b(the|a|an)\b/g,'').replace(/\s+/g,' ').trim();
function bank(sec,format='mixed',viewId=null,extensions=true){let out=[];for(const v of sec.views){if((viewId&&v.id!==viewId)||(!extensions&&v.extension))continue;v.targets.forEach((p,i)=>{const types=format==='locate'?['locate']:format==='typed'?['typed']:format==='choice'?['choice']:['choice','locate'];for(const type of types)out.push({id:p.id?`${sec.id}/${p.id}/${type}`:`${sec.id}/${v.id}/${i}/${type}`,section:sec.id,view:v.id,target:i,type,regionGroup:p.group,worksheetNumber:p.number,concept:p.concept,a:p.name,aliases:p.aliases,why:p.teach,hint:v.regional?'Orient yourself using the view and follow the printed callout.':p.teach.split('.')[0]+'.',q:type==='locate'?`Locate the ${p.name.toLowerCase()}${v.regional?' ('+p.common.toLowerCase()+')':''}.`:`Name the structure at marker ${p.number||i+1}.`,options:shuffle([p.name,...shuffle([...new Set(v.targets.filter(x=>x.name!==p.name).map(x=>x.name))]).slice(0,3)])});});}
if(!viewId&&format!=='locate')sec.facts.filter(x=>extensions||!x.q.startsWith('Extension:')).forEach((x,i)=>out.push({...x,id:x.originalId||`${sec.id}/concept/${i}`,section:sec.id,type:'choice',options:shuffle(x.options),aliases:[]}));return out;}
