// Clip the original printed path to the current crop and anchor at its first visible point.
function printedAnchor(path,box){
 const [x,y,w,h]=box;
 for(let i=1;i<path.length;i++){
  const [ax,ay]=path[i-1],[bx,by]=path[i],dx=bx-ax,dy=by-ay;let enter=0,exit=1,visible=true;
  for(const [p,q] of [[-dx,ax-x],[dx,x+w-ax],[-dy,ay-y],[dy,y+h-ay]]){
   if(p===0){if(q<0){visible=false;break;}}
   else if(p<0)enter=Math.max(enter,q/p);else exit=Math.min(exit,q/p);
  }
  if(visible&&enter<=exit)return [ax+enter*dx,ay+enter*dy];
 }
 return null;
}
