function study(){
 const s=section(),v=state.activity==='learn'?null:currentView(),p=v?.targets[state.target],tab=state.lessonTab||'structure';
 const tabs=`<div class="card-tabs" aria-label="Teaching card">${[['structure',p?'Structure':'Overview'],['memory','Memory cues'],['check','Recall cards']].filter(([id])=>v||id!=='check').map(([id,label])=>`<button data-lesson-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div>`;
 let lesson=tab==='check'?factCard(s):tab==='memory'?`<h2>Make it stick</h2><div class="memory"><p>${esc(p?.memory||v?.memory||s.memory)}</p></div>${p?.spelling?`<h3>Spelling cue</h3><p>${esc(p.spelling)}</p>`:''}<h3>A common mix-up</h3><p>${esc(s.trap)}</p>`:`<p class="eyebrow">${p?`STRUCTURE ${state.target+1}`:'UNDERSTAND THE MAP'}</p><h2>${esc(p?p.name:s.tag)}</h2>${p?.common?`<p class="region-common">${esc(p.common)} · Worksheet ${p.number}</p>`:''}<p>${esc(p?p.teach:v?.note||s.summary)}</p>${v?.targets.length?`<div class="step-buttons"><button data-action="prev-target" aria-label="Previous structure">←</button><span>${regionPosition(v)}</span><button data-action="next-target" aria-label="Next structure">→</button></div>`:''}`;
 return `${courseTrail()}${heading(s)}<div class="toolbar">${sectionPicker()}${viewPicker(s)}${v&&!v.studyOnly?`<label class="toggle"><input id="labels" type="checkbox" ${state.labels?'checked':''}><span>Show all labels</span></label>`:''}<button class="primary" data-mode="practice">Practice this section ↗</button>${s.id==='cells'?'<a href="chapter3/" class="cell-studio-link">Interactive diagrams & labs ↗</a>':''}</div><div class="workspace ${!v?'text-study':''}">${v?diagram(v):`<section class="lesson fact-card">${factCard(s)}</section>`}<div class="lesson-stack"><section class="lesson">${tabs}${lesson}</section></div></div>`;
}
