function factCard(s){const i=Math.min(state.factPage||0,s.facts.length-1),x=s.facts[i];return `<p class="eyebrow">RECALL CARD ${i+1}${x.topic?` · ${esc(x.topic)}`:''}</p><h2>${esc(x.q)}</h2>${state.factReveal?`<div class="fact-answer"><h3>${esc(x.a)}</h3><p>${esc(x.why)}</p></div>`:'<button class="primary" data-action="reveal-fact">Reveal explanation</button>'}${x.sourceUrl?`<a class="textbook-link" href="${esc(x.sourceUrl)}" target="_blank" rel="noopener">Read this topic in OpenStax ↗</a>`:''}${pager('factPage',i,s.facts.length)}`;}
function legacyRegionDraft(){try{const d=JSON.parse(localStorage.getItem('anatomy-atlas-progress-v1')||'null');return Array.isArray(d?.answers)&&d.answers.length===52&&d.answers.every(a=>typeof a==='string'&&a.length<500)&&d.answers.some(a=>a.trim())?d:null;}catch{return null;}}
function importRegionDraft(){const legacy=legacyRegionDraft();if(!legacy)return;const questions=bank(sections.find(s=>s.id==='body-regions'),'typed').filter(q=>q.view).map(q=>({...q,importedAnswer:legacy.answers[q.worksheetNumber-1],importedAssisted:!!legacy.answers[q.worksheetNumber-1].trim()}));start(false,questions.map(q=>({q})));}
function spellingDistance(a,b){const d=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=0;i<=a.length;i++)d[i][0]=i;for(let j=0;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1);}return d[a.length][b.length];}
function regionFeedback(q,value){if(q.section!=='body-regions'||q.type!=='typed'||!value||value==='Skipped')return '';const a=normalize(value);if(a.length>100)return 'Review the regional term and try a shorter answer.';const other=sections.find(s=>s.id==='body-regions').views.flatMap(v=>v.targets).find(p=>[p.name,...p.aliases].some(x=>normalize(x)===a));if(other)return `That names the ${other.common.toLowerCase()} region. Compare its location with the highlighted callout.`;const nearest=[q.a,...q.aliases].map(term=>({term,d:spellingDistance(a,normalize(term))})).sort((x,y)=>x.d-y.d)[0];const n=Math.max(a.length,normalize(nearest.term).length);return nearest.d<= (n<4?0:n<=7?1:n<=12?2:3)&&nearest.d/n<=.26?`Possible spelling mix-up: “${value}” → “${nearest.term}”. This is not counted correct; compare the letters and try it again.`:'Compare the highlighted region with the term and location below.';}
function setup(exam=false){const s=section(),count=examSections().reduce((n,x)=>n+bank(x,'mixed',null,false).length,0);return `<div class="setup-heading"><p class="eyebrow">${exam?'CONNECT THE WHOLE PICTURE':'ACTIVE RECALL'}</p><h1>${exam?(state.courseChapter?'Chapter '+state.courseChapter+' exam':'Custom exam'):`Practice ${s.title.toLowerCase()}`}</h1><p class="intro">${exam?'Questions from your selected chapter coverage. Answers and explanations appear after you submit.':'Name structures, locate them on diagrams, and explain the relationships. Get feedback after every answer.'}</p></div><div class="setup-grid ${s.id==='body-regions'?'region-setup':''}"><section class="lesson setup-card"><span class="eyebrow">${exam?'EXAM SETTINGS':'BUILD YOUR PRACTICE'}</span>${exam&&!state.courseChapter?'<label>Include chapter<select id="custom-chapter"><option value="all">Chapters 1–3</option value="1">Chapter 1</option><option value="2">Chapter 2</option><option value="3">Chapter 3 concepts</option></select></label>':''}${exam?`<label>Exam length<select id="exam-length"><option value="40">40 questions · balanced review</option><option value="80">80 questions · deeper review</option><option id="exam-all" value="all">Complete bank (${count} questions)</option></select></label><label class="check-row"><input type="checkbox" id="extensions">Include membrane extension material (Ch. 4, 9, 13)</label><p class="muted">Untimed. Includes organ identification, location and concepts from the chapters listed here. Diagram questions use numbered markers.</p>`:`<p>Start with 10 mixed questions from this section.</p>${s.id==='body-regions'&&legacyRegionDraft()?'<div class="memory"><b>Saved answers found in your original atlas</b><p>Import them as an ungraded draft. Saved answers count as assisted because prior label use is unknown. The original atlas is unchanged.</p><button data-action="import-regions">Import original atlas draft</button></div>':''}<details class="practice-customize"><summary>Customize practice</summary><label>Answer format<select id="format"><option value="mixed" ${state.format==='mixed'?'selected':''}>Mixed · identify, locate & concepts</option><option value="choice" ${state.format==='choice'?'selected':''}>Multiple choice</option><option value="typed" ${state.format==='typed'?'selected':''}>Type labels · choose concepts</option><option value="locate" ${state.format==='locate'?'selected':''} ${!s.views.some(v=>v.targets.length)?'disabled':''}>Locate on the diagram</option></select></label>${s.views.some(v=>v.targets.length)?`<label>Practice scope<select id="scope"><option value="section">Entire section</option>${s.views.filter(v=>v.targets.length).map(v=>`<option value="${v.id}">${esc(v.title)}</option>`).join('')}</select></label>`:''}${s.id==='body-regions'?'<label>Body area<select id="practice-region-group"><option value="all">All body regions</option><option value="head">Head & neck</option><option value="trunk">Trunk</option><option value="upper">Upper limb</option><option value="lower">Lower limb</option></select></label>':''}<label>Session length<select id="practice-length"><option value="10">10 questions</option><option value="20">20 questions</option><option value="all">All available questions</option></select></label></details><p class="muted">Hints are available. An answer given with a hint counts as assisted, so your independent recall score stays meaningful.</p>`}<button class="primary large" data-action="${exam?'start-exam':'start-practice'}">${exam?'Begin full exam':'Start practice'} →</button></section><section class="lesson"><h2>${exam?'Every section, one session.':'Look. Recall. Locate.'}</h2>${exam?`<ol class="coverage">${examSections().map(x=>`<li>${esc(x.title)}<span>Chapter ${x.chapter}</span></li>`).join('')}</ol>`:`<div class="practice-steps"><p><b>01</b> Study with all labels visible.</p><p><b>02</b> Hide the labels and test your recall.</p><p><b>03</b> Retry missed questions until they stick.</p></div><div class="memory"><b>Your memory cue</b><p>${esc(s.memory)}</p></div>`}<p class="muted small">${Object.keys(state.stats).length} questions answered on this browser. No account needed.</p></section></div>`;}
function start(exam=false,retry=null){let pool;if(retry){pool=shuffle(retry.map(r=>({...r.q,options:r.q.options?shuffle(r.q.options):undefined})));}else if(exam){const ex=$('#extensions').checked,groups=shuffle(examSections().map(s=>shuffle(bank(s,'mixed',null,ex))));const n=$('#exam-length').value;pool=[];while(groups.some(g=>g.length)&&(n==='all'||pool.length<Number(n)))for(const g of groups){if(g.length&&(n==='all'||pool.length<Number(n)))pool.push(g.pop());}pool=shuffle(pool);}else{state.format=$('#format').value;const scope=$('#scope')?.value||'section';pool=shuffle(bank(section(),state.format,scope==='section'?null:scope));if(section().id==='body-regions'){const group=$('#practice-region-group')?.value||'all';if(group!=='all')pool=pool.filter(q=>q.regionGroup===group);}const n=$('#practice-length').value;if(n!=='all')pool=pool.slice(0,Number(n));}if(!pool.length){if(typeof window!=='undefined')alert('Choose at least one chapter or an available question format.');return;}state.reviewPage=0;state.resultSummary=false;state.overview=false;state.session={exam,questions:pool,index:0,records:[],answered:false,hint:false,started:Date.now(),feedback:null,draft:pool[0].importedAnswer||'',regionGroup:!exam&&!retry&&section().id==='body-regions'?($('#practice-region-group')?.value||'all'):'all'};state.mode=exam?'exam':'practice';state.zoom=1;render();focusQuestion();}
function focusQuestion(){setTimeout(()=>{$('#question-heading')?.focus({preventScroll:true});},0);}
function question(){const se=state.session,q=se.questions[se.index],s=sections.find(x=>x.id===q.section),v=s.views.find(x=>x.id===q.view),feedback=se.feedback;return `<div class="session-top"><span class="eyebrow">${se.exam?'FULL EXAM':'PRACTICE'} / ${esc(s.title).toUpperCase()}</span><button data-action="exit-session">End session</button></div><div class="progress-info"><span>Question ${se.index+1} of ${se.questions.length}</span><span>${se.exam?'Feedback at the end':`${se.records.filter(r=>r.correct&&!r.assisted).length} independently correct`}</span></div><progress max="${se.questions.length}" value="${se.index}"></progress><div class="question-heading"><span class="question-type">${q.type==='locate'?'LOCATE':q.view?'IDENTIFY':'UNDERSTAND'}</span><h1 id="question-heading" tabindex="-1">${esc(q.q)}</h1></div><div class="workspace quiz-workspace ${!v?'concept-question':''}">${v?diagram(v,{quiz:true,target:q.target,locate:q.type==='locate',reveal:se.answered&&!se.exam}):''}<section class="lesson answer-panel">${q.type==='locate'?`<p>Choose the marker on the diagram. Every numbered marker is a selectable target.</p>`:q.type==='typed'?`<form id="answer-form">${q.importedAssisted?'<p class="focus-note">Imported answer · prior label use unknown; this answer counts as assisted.</p>':''}<label for="typed-answer">Your answer</label><input id="typed-answer" name="answer" value="${se.answered?esc(feedback.answer):esc(se.draft||'')}" autocomplete="off" spellcheck="false" placeholder="Type the anatomical term…" ${se.answered?'disabled':''}><button class="primary" ${se.answered?'disabled':''}>Check answer</button></form>`:`<div class="choices">${q.options.map((o,i)=>`<button data-answer="${i}" ${se.answered?'disabled':''} class="${se.answered?(se.exam?(o===feedback?.answer?'recorded':''):(o===q.a?'correct':o===feedback?.answer?'incorrect':'')):''}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>`}${!se.exam&&!se.answered?`<button class="hint-button" data-action="hint">${se.hint?'Hint shown · answer will count as assisted':'Need a hint?'}</button>${se.hint?`<div class="hint">${esc(q.hint)}</div>`:''}`:''}${se.answered?`<div class="feedback ${se.exam?'neutral':feedback.correct?'good':'wrong'}" role="status">${se.exam?'<b>Answer recorded.</b><p>Continue when you’re ready. Review all answers after submission.</p>':`<b>${feedback.correct?(feedback.assisted?'Correct with help.':'Correct.'):feedback.answer==='Skipped'?'Skipped.':'Not quite.'}</b>${feedback.spelling?`<p class="spelling-feedback">${esc(feedback.spelling)}</p>`:''}<p><strong>${esc(q.a)}</strong> — ${esc(q.why)}</p>`}</div><button class="primary large" data-action="next-question">${se.index===se.questions.length-1?(se.exam?'Submit exam':'See results'):'Next question'} →</button>`:`<button class="skip-question" data-action="skip-question">Skip question</button>`}</section></div>`;}
function answer(value){const se=state.session;if(!se||se.answered)return;const q=se.questions[se.index];let correct=false,display=value;if(q.type==='locate'&&typeof value==='number'){correct=value===q.target;const v=sections.find(x=>x.id===q.section).views.find(x=>x.id===q.view);display=v.targets[value].name;}else correct=[q.a,...(q.aliases||[])].some(x=>normalize(x)===normalize(value));const record={q,answer:display,correct,assisted:se.hint||!!q.importedAssisted,spelling:correct?'':regionFeedback(q,display)};se.records.push(record);se.feedback=record;se.answered=true;const old=state.stats[q.id]||{attempts:0,correct:0};state.stats[q.id]={attempts:old.attempts+1,correct:old.correct+(correct&&!record.assisted?1:0),lastCorrect:correct,assisted:record.assisted,updatedAt:Date.now()};if(q.canonicalId){try{const cell=JSON.parse(localStorage.getItem('soma-cell-studio-v1')||'{}');cell.stats=cell.stats||{};cell.stats[q.canonicalId]={attempts:(cell.stats[q.canonicalId]?.attempts||0)+1,lastCorrect:correct,assisted:record.assisted,updatedAt:Date.now()};localStorage.setItem('soma-cell-studio-v1',JSON.stringify(cell));}catch{state.storageError=true;}}persist();render();}
function reviewDiagram(q){const s=sections.find(s=>s.id===q.section),v=s?.views.find(v=>v.id===q.view);if(!v)return `<section class="lesson"><p class="eyebrow">CONCEPT REVIEW</p><h2>${esc(s?.title)}</h2><p>${esc(s?.memory)}</p></section>`;const p=v.targets[q.target],[cx,cy,cw,ch]=v.focusBox||p.detail||[0,0,...v.size];return `<figure class="review-figure"><figcaption>${esc(v.title)} · Marker ${p.number||q.target+1}</figcaption><div class="review-image"><div class="review-image-inner" style="--ratio:${cw/ch}"><svg class="anatomy-art" viewBox="${cx} ${cy} ${cw} ${ch}"><image href="assets/${v.src}" width="${v.size[0]}" height="${v.size[1]}"/></svg><span class="review-target" style="left:${(p.x*v.size[0]/100-cx)/cw*100}%;top:${(p.y*v.size[1]/100-cy)/ch*100}%" aria-hidden="true"></span></div></div><p>${esc(p.name)}</p></figure>`;}
function results(){const se=state.session,r=se.records,good=r.filter(x=>x.correct&&!x.assisted).length,assisted=r.filter(x=>x.correct&&x.assisted).length,miss=r.filter(x=>!x.correct||x.assisted),i=Math.min(state.reviewPage||0,r.length-1),x=r[i];return `<div class="result-heading"><div><p class="eyebrow">${se.exam?'EXAM COMPLETE':'PRACTICE COMPLETE'}</p><h1>${good===r.length?'Beautifully recalled.':'Your next step is clear.'}</h1><p class="intro">${good} of ${r.length} independently correct${assisted?` · ${assisted} correct with help`:''}. Review one answer at a time.</p></div><div class="score">${Math.round(good/r.length*100)}<span>%</span></div></div><div class="toolbar"><button class="primary" data-action="retry-missed" ${!miss.length?'disabled':''}>Practice missed & assisted (${miss.length})</button><button data-action="back-study">Return to study</button><button data-action="new-session">New ${se.exam?'exam':'practice'}</button><button data-action="result-summary">${state.resultSummary?'Answer review':'Section scores'}</button></div>${state.resultSummary?`<section class="result-sections">${sections.filter(s=>r.some(x=>x.q.section===s.id)).map(s=>{const a=r.filter(x=>x.q.section===s.id),n=a.filter(x=>x.correct&&!x.assisted).length;return `<div><span>${esc(s.title)}</span><b>${n} / ${a.length}</b><progress max="${a.length}" value="${n}"></progress></div>`;}).join('')}</section>`:`<div class="review-page">${reviewDiagram(x.q)}<section class="lesson"><p class="eyebrow">ANSWER ${i+1} · ${x.assisted?'ASSISTED':x.correct?'CORRECT':x.answer==='Skipped'?'SKIPPED':'REVIEW'}</p><h2>${esc(x.q.q)}</h2><p>Your answer: <strong>${esc(x.answer)}</strong></p>${x.spelling?`<p class="spelling-feedback">${esc(x.spelling)}</p>`:''}<p>Correct answer: <strong>${esc(x.q.a)}</strong></p><p>${esc(x.q.why)}</p><button data-review-section="${x.q.section}" data-review-view="${x.q.view||''}" data-review-target="${x.q.target??0}">Study this topic ↗</button>${pager('reviewPage',i,r.length)}</section></div>`}`;}

function sourcesPage(){const i=state.sourcePage||0;const pages=[
 ['How to study','<ol class="help-list"><li>Choose a section and diagram. Select a number and follow its original printed line to the structure.</li><li>Turn on “Show all labels” for the complete numbered key. Hide it to test yourself.</li><li>Use “Whole figure” to see context, or “Enlarge detail” for a closer look.</li><li>Switch teaching cards between Structure, Memory cues and Recall cards.</li><li>Practice a section, then take a full exam. Review and retry missed answers.</li></ol>'],
 ['Scope & controls','<p>This introductory atlas covers major organs, cavities, membranes and terminology from Chapter 1, plus Chapter 2 chemistry and Chapter 3 cell biology. Later-chapter illustrations make small structures visible; membrane extension content is marked and excluded from standard exams.</p><p>Use Previous and Next to read recall cards and exam reviews without scrolling. Tab moves between controls; Enter or Space selects.</p><p>Numbers sit at the label ends of original printed callout lines, or at the visible ends of those same lines in close-ups. Follow the printed line to the structure. Images without printed leaders use direct markers or simple connectors. Plane highlights trace the entire selected cutting surface.</p>'],
 ['Your learning history','<p>Scores and preferences stay in this browser. They are not synchronized across devices. Clearing browser data removes them.</p><button data-action="reset-progress">Reset local learning history</button>'],
 ...sources.map(s=>[s.title,`<div class="source-item"><p>${esc(s.text)}</p><a href="${s.url}" target="_blank" rel="noopener">View original source ↗</a></div>`]),
 ['Extra membrane worksheet','<p><a href="assets/serosa-numbered.jpg" target="_blank">Open the numbered serous-membrane worksheet ↗</a></p><p>Answer key: 1. Visceral pericardium · 2. Pericardial cavity · 3. Parietal pericardium · 4. Air space in the balloon analogy · 5. Balloon.</p><p>Access for free at <a href="https://openstax.org">openstax.org</a>. No OpenStax endorsement is implied.</p>']
 ];const page=pages[i%pages.length];return `<p class="eyebrow">BUILT FOR UNDERSTANDING</p><h1>Sources & study guide</h1><div class="source-pages"><section class="lesson"><h2>${esc(page[0])}</h2>${page[1]}</section>${pager('sourcePage',i,pages.length)}</div>`;}

function render(){if(typeof window!=='undefined')saveCoursePosition();if(typeof window!=='undefined')document.querySelector('.planes3d-card')?.cleanup3D?.();let body;if(state.mode==='review')body=atlasReview();else if(state.mode==='sources')body=sourcesPage();else if(state.mode==='results')body=results();else if(state.mode==='study')body=study();else body=state.session?question():setup(state.mode==='exam');$('#app').innerHTML=header()+`<div class="shell">${sidebar()}<main id="main">${body}${footer()}</main></div>`;bind();syncPlanes();}
function leave(){return !state.session||state.mode==='results'||confirm('Leave this unfinished session? Answers already submitted remain in local learning history.');}
function navigate(mode){if(!leave())return;state.mode=mode;state.session=null;state.zoom=1;if(state.format==='locate'&&!section().views.some(v=>v.targets.length))state.format='mixed';render();}
function selectSection(id){if(!leave())return;state.section=id;state.courseChapter=sections.find(s=>s.id===id).chapter;if(id==='organs')state.bookSection='1.2';else if(['body-regions','cavities','membranes','abdomen','planes','directions'].includes(id))state.bookSection='1.6';else if(id==='foundations')state.bookSection='1.1';state.regionGroup='all';state.activity='explore';state.figurePage=0;state.factPage=0;state.factReveal=false;state.lessonTab='structure';state.overview=false;state.view=0;state.target=0;state.zoom=1;state.mode='study';state.session=null;persist();render();}
function bind(){
 document.querySelector('#region-group')?.addEventListener('change',e=>{state.regionGroup=e.target.value;state.target=Math.max(0,currentView().targets.findIndex(p=>state.regionGroup==='all'||p.group===state.regionGroup));render();});
 document.querySelector('#region-search')?.addEventListener('change',e=>{const value=normalize(e.target.value),i=currentView().targets.findIndex(p=>[p.name,p.common,...p.aliases].some(n=>normalize(n)===value));if(i>=0){state.regionGroup='all';state.target=i;state.lessonTab='structure';render();}else{e.target.setCustomValidity('Choose a region from this view, or switch Anterior / Posterior.');e.target.reportValidity();}});
 document.querySelector('#region-search')?.addEventListener('input',e=>e.target.setCustomValidity(''));
 document.querySelectorAll('[data-region-page]').forEach(b=>b.onclick=()=>{const ids=currentView().targets.map((p,i)=>({p,i})).filter(x=>!state.regionGroup||state.regionGroup==='all'||x.p.group===state.regionGroup),page=Math.floor(Math.max(0,ids.findIndex(x=>x.i===state.target))/8);state.target=ids[(page+Number(b.dataset.regionPage))*8].i;render();});
 document.querySelectorAll('.region-marker').forEach(g=>g.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&g.getAttribute('aria-disabled')!=='true'){e.preventDefault();g.onclick?.(e);document.querySelector(`.region-marker[data-pin="${g.dataset.pin}"]`)?.focus();}});
 document.querySelector('.skip')?.addEventListener('click',e=>{e.preventDefault();document.querySelector('#main')?.setAttribute('tabindex','-1');document.querySelector('#main')?.focus();});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{state.activity=b.dataset.activity;state.mode='study';render();});document.querySelector('[data-revisit]')?.addEventListener('click',()=>{const qs=atlasMissed();if(qs.length)start(false,qs.map(q=>({q})));});document.querySelectorAll('[data-exam-chapter]').forEach(b=>b.onchange=()=>{state.examChapters=[...document.querySelectorAll('[data-exam-chapter]:checked')].map(x=>Number(x.value));render();});document.querySelector('#chapter-switch')?.addEventListener('change',e=>{if(leave())location.href='./#/chapter/'+e.target.value;});document.querySelector('#atlas-topic')?.addEventListener('change',e=>selectSection(e.target.value));$('#detail-select')?.addEventListener('change',e=>{state.figurePage=Number(e.target.value);state.overview=false;render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const id=b.dataset.page;state[id]=(state[id]||0)+Number(b.dataset.delta);state.factReveal=false;render();});document.querySelectorAll('[data-lesson-tab]').forEach(b=>b.onclick=()=>{state.lessonTab=b.dataset.lessonTab;render();});$('#extensions')?.addEventListener('change',e=>{const count=sections.reduce((n,s)=>n+bank(s,'mixed',null,e.target.checked).length,0);$('#exam-all').textContent=`Complete bank (${count} questions)`;});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>navigate(b.dataset.mode));document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>selectSection(b.dataset.section));$('#section-select')?.addEventListener('change',e=>selectSection(e.target.value));$('#view-select')?.addEventListener('change',e=>{state.view=Number(e.target.value);state.regionGroup='all';state.figurePage=0;state.overview=false;state.lessonTab='structure';state.target=0;state.zoom=1;render();});$('#labels')?.addEventListener('change',e=>{state.labels=e.target.checked;persist();render();});document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{if(b.getAttribute?.('aria-disabled')==='true')return;const n=Number(b.dataset.pin);if(state.session){if(state.session.questions[state.session.index].type==='locate')answer(n);}else{state.target=n;state.lessonTab='structure';render();}});document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{state.zoom=Math.max(1,Math.min(2,state.zoom+Number(b.dataset.zoom)*.25));render();});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(state.session.questions[state.session.index].options[Number(b.dataset.answer)]));$('#typed-answer')?.addEventListener('input',e=>{if(state.session&&!state.session.answered){state.session.draft=e.target.value;if(typeof window!=='undefined')saveCoursePosition();}});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#typed-answer').value.trim();if(value)answer(value);else $('#typed-answer').focus();});document.querySelectorAll('[data-review-section]').forEach(b=>b.onclick=()=>{const s=sections.find(x=>x.id===b.dataset.reviewSection);state.section=s.id;state.courseChapter=s.chapter;state.bookSection=s.id==='body-regions'?'1.6':state.bookSection;state.activity='explore';state.regionGroup='all';state.view=Math.max(0,s.views.findIndex(v=>v.id===b.dataset.reviewView));state.target=Number(b.dataset.reviewTarget);state.mode='study';state.session=null;state.zoom=1;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();const action=b.dataset.action;switch(action){case'import-regions':if(confirm('Import your original atlas answers into a new Soma practice draft? Your original answers will be kept. Imported answers count as assisted.'))importRegionDraft();break;case'toggle-overview':state.overview=!state.overview;render();break;case'reveal-fact':state.factReveal=true;render();break;case'result-summary':state.resultSummary=!state.resultSummary;render();break;case'home':navigate('study');break;case'prev-target':case'next-target':{const n=currentView().targets.length;if(currentView().regional){const ids=currentView().targets.map((p,i)=>({p,i})).filter(x=>!state.regionGroup||state.regionGroup==='all'||x.p.group===state.regionGroup).map(x=>x.i),at=ids.indexOf(state.target);state.target=ids[(Math.max(0,at)+(action==='next-target'?1:-1)+ids.length)%ids.length];}else state.target=(state.target+(action==='next-target'?1:-1)+n)%n;render();break;}case'start-practice':start();break;case'start-exam':start(true);break;case'hint':state.session.hint=true;render();break;case'skip-question':answer('Skipped');break;case'next-question':if(state.session.index===state.session.questions.length-1){state.mode='results';}else{state.session.index++;state.session.answered=false;state.session.hint=false;state.session.feedback=null;state.session.draft=state.session.questions[state.session.index].importedAnswer||'';}state.zoom=1;state.overview=false;render();focusQuestion();break;case'exit-session':if(confirm('End this session now? Unanswered questions will be recorded as skipped.')){const se=state.session;for(let i=se.index+(se.answered?1:0);i<se.questions.length;i++)se.records.push({q:se.questions[i],answer:'Skipped',correct:false,assisted:false});state.mode='results';render();}break;case'retry-missed':start(false,state.session.records.filter(x=>!x.correct||x.assisted).map(r=>{const {importedAssisted,importedAnswer,...q}=r.q;return {...r,q};}));break;case'back-study':state.session=null;state.mode='study';render();break;case'new-session':{const mode=state.session.exam?'exam':'practice';state.session=null;state.mode=mode;render();break;}case'reset-progress':location.href='./#/review';break;}});}
function examSections(){return sections.filter(s=>state.courseChapter?s.chapter===state.courseChapter:(state.examChapters||[1,2,3]).includes(s.chapter));}
function courseTrail(){const c=activeChapter(),book=chapters.find(x=>x.id===c)?.sections.find(x=>x[0]===state.bookSection);return `<p class="breadcrumb"><a href="./">Chapters</a> / <a href="./#/chapter/${c}">Chapter ${c}</a>${book?' / '+book[0]:''}${book?` · <a href="${textbook(book)}" target="_blank" rel="noopener">Read textbook ↗</a>`:''}</p><div class="activity-subnav"><button data-activity="learn" aria-pressed="${state.activity==='learn'}">Learn</button><button data-activity="explore" aria-pressed="${state.activity!=='learn'}" ${!section().views.length?'disabled title="Diagrams are not yet available for this essentials section"':''}>Explore</button><button data-mode="practice">Practice</button><a href="#chapter/${c}/section/${state.bookSection||c+'.1'}/${state.section}/review">Review</a></div>`;}
function sectionPicker(){return activeChapter()===1?`<label>Activity <select id="atlas-topic">${sections.filter(x=>x.chapter===1).map(x=>`<option value="${x.id}" ${x.id===state.section?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`:'';}
let applyingAtlasRoute=false;
function atlasMissed(){return (state.sectionReview?[section()]:examSections()).flatMap(s=>[...new Map([...bank(s,'mixed'),...bank(s,'typed')].map(q=>[q.id,q])).values()]).filter(q=>state.stats[q.id]?.lastCorrect===false||state.stats[q.id]?.assisted);}
function atlasReview(){const qs=atlasMissed();return `${courseTrail()}<section class="lesson"><p class="eyebrow">${state.sectionReview?'SECTION':'CHAPTER'} REVIEW</p><h1>${qs.length?qs.length+' questions to revisit':'Begin with a little practice.'}</h1><p>${qs.length?'These questions were missed or answered with help on your latest attempt.':'No missed or assisted answers are recorded for this chapter yet. Older records contain totals only.'}</p><button class="primary" data-revisit ${!qs.length?'disabled':''}>Practice missed & assisted →</button><button data-mode="practice">Open section practice</button></section>`;}
function saveCoursePosition(){if(!canSaveProgress())return;try{const c=activeChapter(),route=state.session&&state.mode!=='results'?'quiz':state.mode==='results'?'results':state.mode==='exam'?(state.courseChapter?`chapter/${c}/exam`:'custom-exam'):state.mode==='sources'?'sources':state.mode==='review'?`chapter/${c}/review`:`chapter/${c}/section/${state.bookSection||c+'.1'}/${state.section}/${state.mode}/${state.activity||'explore'}/${state.factPage||0}/${state.view||0}/${state.target||0}/${state.regionGroup||'all'}`;if(!applyingAtlasRoute&&location.hash.slice(1)!==route)history.pushState(null,'','#'+route);if(state.mode!=='sources'&&state.mode!=='results')localStorage.setItem('soma-resume-v1',JSON.stringify({label:`Chapter ${c} · ${state.session?'unfinished practice':section().title}`,url:'atlas.html#'+route}));localStorage.setItem('soma-atlas-draft-v1',JSON.stringify({state}));}catch{}}
function refreshRegionalDraft(session){if(!session)return;const current=new Map(['mixed','typed'].flatMap(format=>bank(sections.find(s=>s.id==='body-regions'),format)).map(q=>[q.id,q]));const refresh=q=>q?.section==='body-regions'&&current.has(q.id)?{...q,...current.get(q.id)}:q;session.questions=session.questions.map(refresh);session.records=(session.records||[]).map(r=>({...r,q:refresh(r.q)}));if(session.feedback)session.feedback={...session.feedback,q:refresh(session.feedback.q)};}
function applyCourseRoute(){applyingAtlasRoute=true;const parts=location.hash.slice(1).split('/');if(parts[0]==='chapter'){state.courseChapter=[1,2,3].includes(Number(parts[1]))?Number(parts[1]):1;if(state.courseChapter===3){location.replace('chapter3/');return;}if(parts[2]==='section'){state.bookSection=parts[3];state.section=sections.some(s=>s.id===parts[4]&&s.chapter===state.courseChapter)?parts[4]:(state.courseChapter===2?'chemistry':'foundations');state.mode=['practice','review'].includes(parts[5])?parts[5]:'study';state.sectionReview=state.mode==='review';state.activity=parts[6]||(!currentView()?'learn':'explore');state.factPage=Math.max(0,Math.min(section().facts.length-1,Number(parts[7])||0));state.view=Math.max(0,Math.min(section().views.length-1,Number(parts[8])||0));state.target=Math.max(0,Math.min((currentView()?.targets.length||1)-1,Number(parts[9])||0));state.regionGroup=['all','head','trunk','upper','lower'].includes(parts[10])?parts[10]:'all';state.session=null;}else if(parts[2]==='exam'){state.mode='exam';state.session=null;}else if(parts[2]==='review'){state.section=state.courseChapter===2?'chemistry':'foundations';state.mode='review';state.sectionReview=false;state.session=null;}}
else if(parts[0]==='custom-exam'){state.courseChapter=null;state.mode='exam';state.session=null;}else if(parts[0]==='sources'){state.mode='sources';state.session=null;}else if(['quiz','results'].includes(parts[0])){try{const d=JSON.parse(localStorage.getItem('soma-atlas-draft-v1')||'{}').state;if(d?.session?.questions?.length&&Number.isInteger(d.session.index)&&d.session.index>=0&&d.session.index<d.session.questions.length&&sections.some(s=>s.id===d.section)){Object.assign(state,d);refreshRegionalDraft(state.session);if(parts[0]==='results')state.mode='results';}else{state.mode='study';state.session=null;}}catch{state.mode='study';state.session=null;}}
render();applyingAtlasRoute=false;}
if(typeof window!=='undefined'){try{document.documentElement.dataset.motion=JSON.parse(localStorage.getItem('soma-motion')||'"on"');}catch{}window.addEventListener('hashchange',()=>{if(leave())applyCourseRoute();else saveCoursePosition();});window.addEventListener('pagehide',saveCoursePosition);if(location.hash)applyCourseRoute();}

render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_study_section',title:'Open anatomy study section',description:'Navigate to a study section when no unfinished quiz is active.',inputSchema:{type:'object',properties:{sectionId:{type:'string',enum:sections.map(s=>s.id)}},required:['sectionId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!sections.some(s=>s.id===input?.sectionId))throw Error('Unknown study section');if(state.session&&state.mode!=='results')throw Error('Finish or end the active quiz first');selectSection(input.sectionId);return {section:state.section,mode:state.mode};}})).catch(()=>{});}catch{}}
